proc sql;
create table MA_fyear as select
a.*,
year(a.date_announced) as year,
b.fyear as comp_fyear,
b.datadate
from MA_manual_check as a left join comp as b
on a.acq_gvkey=b.gvkey and year(a.date_announced)=b.year;

data comp;
	set data.Compustat_Annual;
	where (indfmt='INDL' and datafmt='STD' and popsrc='D' and consol='C');
	*for MtoB; if CSHPRI=. THEN CSHPRI=0; if PRCC_F=. THEN PRCC_F=0; if LT=. THEN LT=0; if PSTKL=. THEN PSTKL=0; if TXDB=. THEN TXDB=0;
	*for FCF_Assets; if oibdp=. THEN oibdp=.; if xint=. THEN xint=0; if txdi=. THEN txdi=0; if CAPX=. THEN CAPX=0;
	*for TobinQ; if BKVLPS=. THEN BKVLPS=0; if TDC=. THEN TDC=0; if CSHO=. THEN CSHO=0;
	*for KZIndex;	if ebitda=. THEN ebitda=0; if CSHPRI=. THEN CSHPRI=0; if PSTKL=. THEN PSTKL=0; if TXDB=. THEN TXDB=0; if CH=. THEN CH=0;
	if DT=. THEN DT=0; if CHE=. THEN CHE=0;  if DVC=. THEN DVC=0; if INTAN=. THEN INTAN=0;
	if XRD=. THEN XRD=0; 
	if aqc=. then aqc=0; 
		if not missing(SEQ) then SHE=SEQ;else
		if nmiss(CEQ,PSTK)=0 then SHE=CEQ+PSTK;else
		if nmiss(AT,LT)=0 then SHE=AT-sum(LT,MIB); 
		else SHE=.; 
	PREF = coalesce(PSTKRV,PSTKL,PSTK); 
	BE = sum(SHE, TXDB, ITCB, -PREF);
	ME = PRCC_C*CSHO;
    YEAR=year(datadate);

%let keepvars = date permno permco shrout vol ret prc bid ask bidlo askhi CFACPR cfacshr ;
%let dropvars = cfacpr cfacshr ncusip bid ask bidlo askhi;

proc sql;
	create table monthly_crsp_raw
    as select a.*, b.shrcd, b.siccd, b.ncusip, b.tsymbol as ticker, b.permco
    from data.crsp_monthly(keep = &keepvars) as a, data.msenames as b
    where year(a.date) >= &beg_year-1 and a.permno=b.permno and b.namedt <= a.date <= b.nameendt and b.shrcd in (10,11) and b.TRDSTAT="A";

**CRSP--Compustat Linking File;
%let start_date='01Jan1973'd; 
%let end_date='31DEC2019'd;
Data CClink; 
	set data.linking_table_upto2019;
	LINKENDDT1=LINKENDDT+0;
	if LINKENDDT1=. then LINKENDDT1='31Dec2019'd; 
	if LINKPRIM="C" or LINKPRIM="P";
	if LINKTYPE^="NR";
	if LINKTYPE^="NU";
	if USEDFLAG^=-1;  
	Begyear=year(LINKDT);
	Endyear=year(LINKENDDT1);
	if Begyear=Endyear THEN Begyear=Begyear-1;

*To adjust for historical SIC code, we first use Compustat historical SIC code: SICH. If SICH is not available, we will use SICCD from CRSP instead;
*Then we use Compustat historical snapshots to get the historical zipcode for each firms.;
proc sql;
create table comp_crsp_zip as select
a.*,
year(datadate) as year,
b.hist_zip 
from data.hist_zip as b left join comp_crsp_combined as a
on a.gvkey=b.gvkey and a.fyear=b.fyear;

create table comp_crsp_zip_sic as select
a.*,
b.sic_his
from comp_crsp_zip as a left join data.Adj_sic as b
on a.gvkey=b.gvkey and a.fyear=b.fyear;
